insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','「会釈」のおじぎの角度はおよそどれですか？','["15度", "30度", "45度", "60度"]'::jsonb,0,'会釈は約15度で、軽いあいさつや職場ですれ違うときに行います。',601,'04 · おじぎ','Berapa kira-kira sudut membungkuk 「会釈」?','会釈 sekitar 15 derajat, dipakai untuk sapaan ringan atau saat berpapasan di tempat kerja.','[{"k": "会釈", "b": "えしゃく", "a": "bungkuk ringan 15°"}, {"k": "角度", "b": "かくど", "a": "sudut"}, {"k": "軽い", "b": "かるい", "a": "ringan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','「敬礼」のおじぎの角度はおよそどれですか？','["15度", "30度", "45度", "90度"]'::jsonb,1,'敬礼は約30度で、お客様への一般的なあいさつや感謝の場面で使います。',602,'04 · おじぎ','Berapa kira-kira sudut membungkuk 「敬礼」?','敬礼 sekitar 30 derajat, dipakai untuk sapaan umum ke tamu atau saat menyampaikan terima kasih.','[{"k": "敬礼", "b": "けいれい", "a": "bungkuk 30°"}, {"k": "一般的", "b": "いっぱんてき", "a": "umum"}, {"k": "感謝", "b": "かんしゃ", "a": "terima kasih"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','「最敬礼」を使う場面として正しいのはどれですか？','["職場ですれ違うとき", "軽いあいさつのとき", "お詫びや深い感謝を伝えるとき", "電話を切るとき"]'::jsonb,2,'最敬礼は約45度で、お詫びや深い感謝など最も丁寧な場面で使います。',603,'04 · おじぎ','Mana situasi yang tepat memakai 「最敬礼」?','最敬礼 sekitar 45 derajat, dipakai pada situasi paling sopan seperti permintaan maaf atau rasa terima kasih yang mendalam.','[{"k": "最敬礼", "b": "さいけいれい", "a": "bungkuk 45°"}, {"k": "お詫び", "b": "おわび", "a": "permintaan maaf"}, {"k": "場面", "b": "ばめん", "a": "situasi"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','お客様を玄関で見送るとき、最も適切なおじぎはどれですか？','["会釈", "敬礼", "最敬礼", "おじぎはしない"]'::jsonb,2,'見送りは感謝を表す大切な場面なので、最敬礼で丁寧に行います。',604,'04 · おじぎ','Saat mengantar tamu pulang di pintu masuk, bungkuk mana yang paling tepat?','Mengantar pulang adalah momen penting untuk menyampaikan terima kasih, jadi dilakukan dengan 最敬礼 yang paling sopan.','[{"k": "見送る", "b": "みおくる", "a": "mengantar pulang"}, {"k": "玄関", "b": "げんかん", "a": "pintu masuk"}, {"k": "感謝", "b": "かんしゃ", "a": "terima kasih"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','正しいおじぎの姿勢はどれですか？','["背中を丸めて頭だけ下げる", "背筋を伸ばし腰から曲げる", "ひざを曲げてしゃがむ", "あごを上げたまま下げる"]'::jsonb,1,'背筋を伸ばし、腰から上体を折るようにしておじぎをします。頭だけ下げるのは失礼です。',605,'04 · おじぎ','Mana postur membungkuk yang benar?','Punggung diluruskan lalu badan dibungkukkan dari pinggang. Menundukkan kepala saja dianggap tidak sopan.','[{"k": "背筋", "b": "せすじ", "a": "punggung"}, {"k": "腰", "b": "こし", "a": "pinggang"}, {"k": "失礼", "b": "しつれい", "a": "tidak sopan"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','おじぎをするときの手の位置として正しいのはどれですか？','["男性は体の横、女性は前で重ねる", "全員がポケットに手を入れる", "全員が後ろで組む", "手は自由にしてよい"]'::jsonb,0,'男性は腕を体の横に自然に伸ばし、女性は両手を前で重ねるのが基本です。ポケットに手を入れてのおじぎは失礼です。',606,'04 · おじぎ','Mana posisi tangan yang benar saat membungkuk?','Pria meluruskan lengan di samping badan, wanita menumpuk kedua tangan di depan. Membungkuk dengan tangan di kantong itu tidak sopan.','[{"k": "手の位置", "b": "てのいち", "a": "posisi tangan"}, {"k": "重ねる", "b": "かさねる", "a": "menumpuk/menyatukan"}, {"k": "基本", "b": "きほん", "a": "dasar"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','会釈の長さ（時間）として適切なのはどれですか？','["約1秒", "約5秒", "約10秒", "見えなくなるまで下げ続ける"]'::jsonb,0,'会釈は約1秒、敬礼は約2〜3秒が目安です。長すぎるおじぎは相手を戸惑わせます。',607,'04 · おじぎ','Berapa lama membungkuk untuk 会釈?','会釈 sekitar 1 detik, 敬礼 sekitar 2–3 detik. Membungkuk terlalu lama membuat lawan bicara bingung.','[{"k": "長さ", "b": "ながさ", "a": "durasi/panjang"}, {"k": "目安", "b": "めやす", "a": "patokan"}, {"k": "戸惑う", "b": "とまどう", "a": "bingung"}]'::jsonb);
insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,pertanyaan_id,penjelasan_id,kata) values ('宿泊分野','お客様と話しながらおじぎをするとき、正しいのはどれですか？','["頭を下げたまま話し続ける", "言葉に合わせておじぎをし、下げたまま話さない", "おじぎの途中で顔だけ上げて話す", "話しながら手を振る"]'::jsonb,1,'おじぎは言葉に合わせて行い、頭を下げたまま話し続けるのは失礼です。',608,'04 · おじぎ','Mana yang benar saat membungkuk sambil berbicara dengan tamu?','Membungkuk dilakukan bersamaan dengan ucapan, dan berbicara terus sambil menunduk itu tidak sopan.','[{"k": "言葉", "b": "ことば", "a": "ucapan"}, {"k": "合わせる", "b": "あわせる", "a": "menyesuaikan"}, {"k": "頭", "b": "あたま", "a": "kepala"}]'::jsonb);
